        conditionsInfoStability: "Stability: starts at 50 (range 0 to 100). In a normal empire it adds 0.6 per point of approval above 50 and subtracts 1 per point below 50; here approval equals happiness because all pops are treated alike. In a gestalt empire there is no happiness: amenities act directly on stability with the same numbers. Jobs such as Enforcers and Soldiers add their stability (a modifier, so the stability effect does not change it). If housing is missing, it subtracts 40 × (missing housing / required housing). Crime is shown but does not change stability; edicts, factions and events are not modelled (use the manual extra stability).",
