        modifierCatTradeConversion: "Exchange rate of job trade (policy)",
        modifierStackTradeConversion: "Each resource receives the trade produced by jobs times its rate; the trade kept has its own rate too. Applied before the empire multipliers.",
        modifierOrder4b: "The trade policy splits the trade produced by jobs between resources according to its exchange rates.",
        modifierOrder4a: "Stability effect: the planet's stability changes the resources produced by jobs (+0.6% per point above 50, −1% per point below). Amenities are not affected.",
        modifierCatStabilityEffect: "Stability effect on job output",
        modifierStackStabilityEffect: "Applies only to the resources produced by jobs, after steps 1–4; not to amenities nor to planetary modifiers.",
