        conditionsCrimeHappiness: "Crime from low happiness",
        conditionsCrimeJobs: "Crime reduction from jobs",
        conditionsCrime: "Crime",
        conditionsDeviancyJobs: "Deviancy reduction from jobs",
        conditionsDeviancy: "Deviancy",
        conditionsFormulaCrime: (pops, happiness, value) => `Crime from pops: 0.02 × (100 − ${happiness} happiness) × ${pops} pops = ${value} (0 at 100 happiness, +2 per pop at 0). Display only: crime does not change stability here.`,
        conditionsDeviancyNote: "Gestalt empire: crime is called Deviancy. There is no happiness, so deviancy produced by pops is not modelled; only job reductions are shown. Display only.",
        conditionsHappinessManual: "Manual extra happiness",
        conditionsStabilityManual: "Manual extra stability",
        conditionsStabilityJobs: "Stability from jobs",
        conditionsCivilians: "Civilians (pops without jobs)",
        breakdownCivilians: "Civilians",
        jobMaintenanceDrone: "Maintenance Drone",
        conditionsSourceManual: "Manual",
        conditionsSourceEstimated: "Estimated",
        conditionsSourceDerived: "Derived",
        conditionsSourceManualTooltip: "Entered by you for sources the simulator does not model.",
        conditionsSourceEstimatedTooltip: "Depends on a simplification of the simulator (1 amenity per pop, all pops alike, approval = happiness).",
        conditionsSourceDerivedTooltip: "Calculated directly from the planet data and the wiki rules.",
        productionInfoColumns: "Produced: every positive monthly amount of the planet. Consumed: every upkeep (jobs, capital, districts, buildings). Net = produced + consumed. Amenities are shown ×100 like jobs and pops (100 = 1); other resources are monthly amounts.",
        productionInfoBreakdown: "Click a Net row to open its breakdown. Lines follow the calculation order (see the Active modifiers panel): job base output, per-job building bonuses, efficiency, % of job output, civilians, stability effect, trade conversion, flat outputs, empire multipliers, then upkeep of capital, districts and buildings. Gross = sum of positive lines, costs = sum of negative lines.",
        productionInfoTrade: (policy, amount, rates) => `Trade conversion (${policy}): this month ${amount} trade from jobs and civilians is split by the policy exchange rates: ${rates}. It happens after job efficiency and the stability effect and before the empire % bonuses, so the converted resources still receive those bonuses.`,
        productionInfoTradeNone: (policy) => `Trade conversion (${policy}): no trade is produced by jobs or civilians, so nothing is converted.`,
        productionInfoExternal: "External income: flat monthly bonuses of the empire (ethics, authority) are listed below the columns, apart from the planet. They are not produced, consumed or net of this planet; the \"total with external income\" line adds them to the planet net.",
        productionInfoCheck: "Consistency check: produced + consumed and the sum of the breakdown lines must equal net (tolerance 0.001); otherwise a bug warning is shown.",
        jobsInfoStaffing: (created, staffed) => `Full staffing: every job created is assumed staffed, one pop per job (now ${created} created, ${staffed} staffed). The slider of each job is only an optional override; extra pops come only from the manual Civilians input in Planetary conditions.`,
        jobsInfoScale: "Jobs, pops, housing and amenities are shown ×100 like the wiki (100 = 1 pop); the calculation uses real units.",
        jobsInfoControls: "Controls of the − / + buttons and the slider: click = ±10 · Ctrl/Cmd+click = ±100 · Shift+click = 100 % (+) or 0 % (−). Changing the staffing only recalculates the economy.",
        jobsInfoStrata: (list) => `Jobs are grouped by stratum. Stratum efficiency (ethics, buildings, Production Policy) joins the job efficiency pool (step 3: floor 0, positive output only). Current: ${list}.`,
        jobsInfoStrataNone: "none",
        jobsInfoNonResource: "Other job effects (stability, crime, defense armies, naval capacity) are listed under the jobs, multiplied by the staffed jobs; they are not resources. Stability and crime from jobs also enter Planetary conditions; job stability is a modifier, so the stability effect does not change it.",
        conditionsInfoNowPops: (staffed, civilians, pops) => `Now: ${staffed} staffed jobs + ${civilians} civilians = ${pops} pops.`,
        conditionsInfoNowHousing: (provided, pops, missing) => `Now: ${provided} housing for ${pops} pops, so ${missing} housing is missing.`,
        conditionsInfoNowAmenities: (provided, lost, usage, available) => `Now: ${provided} provided − (${lost} always lost + ${usage} used by pops) = ${available} available.`,
        conditionsInfoNowHappiness: (amenities, manual, value) => `Now: 50 base ${amenities} from amenities ${manual} manual = ${value} happiness.`,
        conditionsInfoNowStability: (main, mainLabel, jobs, manual, housing, value, effect) => `Now: 50 base ${main} ${mainLabel} ${jobs} jobs ${manual} manual ${housing} missing housing = ${value} stability, which changes job output by ${effect}%.`,
        conditionsInfoNowStabilityApproval: "approval",
        conditionsInfoNowStabilityAmenities: "amenities",
        conditionsInfoCrime: "Crime: each pop produces 0.02 crime per point of happiness below 100 (0 at 100 happiness, 2 at 0). Jobs such as Enforcers reduce it. Shown only: crime does not change stability or output in the simulator.",
        conditionsInfoDeviancy: "Deviancy (gestalt): with no happiness, deviancy from pops is not modelled; only the reduction from jobs is shown. Shown only: it does not change stability or output.",
        conditionsInfoNowCrime: (popsShown, pops, happiness, fromHappiness, fromJobs, total) => `Now: ${popsShown} pops (${pops} in real units) × 0.02 × (100 − ${happiness}) = ${fromHappiness} from pops, ${fromJobs} from jobs, total ${total}.`,
        conditionsInfoNowDeviancy: (fromJobs, total) => `Now: ${fromJobs} from jobs, total ${total}.`,
        conditionsInfoNoPops: "Now: there are no pops, so happiness, stability and crime are not calculated.",
        empireInfoEthics: "Ethics and authority: highlighted effects are applied to the planet: unity and trade % (empire multipliers, step 6), influence (external income, step 7) and worker/specialist efficiency (stratum efficiency, step 3). The others are informational: listed but not calculated.",
        empireInfoNowApplied: (list) => `Now applied: ${list}.`,
        empireInfoNowAppliedNone: "Now applied: none.",
        empireInfoCivics: (count, max) => `Civics: up to ${max} (now ${count}). Only civics allowed by the chosen ethics and authority are listed, and choosing one hides those it excludes. A civic that stops being allowed after an ethics or authority change is removed. Civics affect the planet only where a rule names them (available buildings, designations and policy options, district housing such as Agrarian Idyll); their other effects are not modelled.`,
        empireInfoPolicies: "Policies: Economic Policy changes the % of job output (step 4); Production Policy (gestalt) is treated as stratum efficiency (step 3); Diplomatic Stance is an empire multiplier (step 6). Switching individualist ↔ gestalt resets the policies to the new defaults. Trade League and Holy Covenant assume membership of the federation they need.",
        empireInfoNowTrade: (policy, kept, rest) => `Now: ${policy} keeps ${kept}% of the trade from jobs and civilians${rest ? ` and turns the rest into ${rest}` : ""}. The conversion happens after job efficiency and the stability effect and before the empire % bonuses.`,
        conditionsInfoSources: "Each value is labelled Manual (entered by you), Estimated (relies on a simplification) or Derived (calculated from the data). Manual extra happiness and stability (default 0) cover unmodelled sources such as edicts, factions or events; they are saved with the planet.",
